-- 2407 🏋️ Exercises from the book "dutch-academy-football-coaching-u12-13-technical-and-tactical-practices-from-top" into the exercise catalog (mig 2191).
-- Every practice the book sets out, in OUR OWN WORDS, with app page numbers
-- (the diagram is the book page).  Written by scripts/exercises/sync.py load.
-- Re-runnable: clears this book's exercises first.
BEGIN;
DELETE FROM exercises WHERE book_id = (SELECT id FROM coaching_books WHERE slug = 'dutch-academy-football-coaching-u12-13-technical-and-tactical-practices-from-top');
INSERT INTO exercises (title, category_id, opposition, moment, source_id, book_id, page_from, page_to, source_ref, coach,
  objective, setup, procedure, rules, progressions, coaching_points, players_text, min_players, max_players,
  area_text, area_length_m, area_width_m, duration_min, has_goals, has_keepers, directional, age_text, sort_order)
SELECT v.t, c.id, v.opp, v.m, b.source_id, b.id, v.pf::int, v.pt::int, v.ref, v.coach, v.obj, v.setup, v.proc, v.rules, v.prog, v.cp,
  v.players, v.mn::int, v.mx::int, v.area, v.len::real, v.wid::real, v.dur::real, v.goals::boolean, v.gk::boolean, v.dir::boolean, v.age, v.so
FROM (VALUES
  ('Curved run, open up and turn', 'technical', 'unopposed', 'in_possession', 40, 40, 'Step 1: Practice 1 - Creating Space, Opening Up and Turning in a Passing Combination', NULL, 'Making space with a bent run, letting the ball run across the body to open up, then receiving and turning on the inside of the foot.', 'Rectangle split by a halfway line with a full-size goal at each end. Two blue players in the middle (B and D) next to small cone gates; two orange groups in opposite corners (A/A1 and C/C1), each starting with a ball.', 'A and C play into the middle players at the same moment; each middle player bends his run, lets the ball roll across him, dribbles through the cone gate and finishes into the goal. Then A1 feeds D, who turns on the inside of the foot and passes to C, while C1 feeds B, who turns and passes back to A; the cycle restarts. Rotate who plays in the middle.', NULL, NULL, NULL, '2 middle players + 2 corner groups', 6, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 10),
  ('Four-channel turning circuit to mini goals', 'technical', 'unopposed', 'in_possession', 41, 41, 'Step 1: Practice 2 - Turning Away from an Opponent in a Continuous Passing Circuit', NULL, 'Receiving and turning away from an imaginary opponent using a range of turns.', 'Four side-by-side channels, each with a mini goal at the far end (goals alternate ends). Four servers on the outside, each with a ball, and one player in the middle of each channel.', 'All four servers pass in at the same time; each middle player turns as if escaping a marker and shoots into his channel''s mini goal. The last player collects the ball and dribbles back to the start; everyone moves on one station (server to middle, middle to next server) and the circuit keeps running.', 'Change the turn each time: inside foot, outside foot, step-over and turn, Cruyff turn. Needs at least 9 players; more players speed it up.', 'Put a passive defender in each channel: servers become the passive defenders, defenders become the middle players and middle players move to the next channel.', NULL, 'minimum 9', 9, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 20),
  ('Free dribbling with turns and direction changes', 'technical', 'unopposed', 'in_possession', 42, 42, 'Step 1: Practice 3 - Ball Control and Turning with Quick Change of Direction', NULL, 'Close control, stopping the ball and turning away in different ways.', 'Square marked with cones spaced around the edge; every player has a ball inside it.', 'Players dribble freely, either heading for the edge (between two cones) and turning back, or dribbling at another player and turning away from him to change direction.', 'Vary the turn: inside foot, outside foot, step-over and turn, Cruyff turn.', NULL, NULL, 'whole group, one ball each', NULL, NULL, NULL, NULL, NULL, NULL, false, false, false, 'U12-U13', 30),
  ('Bent-run receive and switch to mini goal', 'technical', 'unopposed', 'in_possession', 44, 44, 'Step 2: Practice 1 - Create Space, Change Direction and Switch of Play', NULL, 'Making space with a curved run, changing direction and switching play with an accurate pass.', 'Half-width area with two mini goals on the far line, one each side. Wide players A and C (full back or winger) on the flanks with balls; central players B and D (centre back or centre midfielder) in the middle.', 'A passes into B, who curves away facing back as if to return it, then opens up quickly and switches play with a pass into the mini goal on the opposite side. C and D then run the same pattern the other way; pairs swap sides now and then.', NULL, NULL, 'Wide player''s pass must be weighted well; central player sells the back pass before turning; switch must be accurate into the goal.', '4 (2 wide, 2 central)', 4, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 40),
  ('Full back-midfield switch of play pattern', 'passing_unopposed', 'unopposed', 'in_possession', 45, 46, 'Step 2: Practice 2 - Switching Play with Quick Passing Combination', NULL, 'Movements and passing combinations to move the ball from one flank to the other.', 'Area with a line across the middle, a cone on each flank and two mini goals on the far line. Full backs A and D on opposite flanks with balls, defensive midfielder B centrally, attacking midfielder or winger C higher up.', 'Full back A dribbles forward round the cone, finds no forward option and turns back; B bends a run, receives and turns inside, then plays into C. C either turns and scores in the far-side mini goal or lays it back for B to finish first time. Then run it from D the other way.', NULL, 'Add two passive defenders in the centre.', 'Full back fakes a forward pass then turns back on the inside foot, accurate pass. Midfielder B keeps some distance from the full back, turns in one movement, weights the forward pass and plays it to the defender''s blind side. C shields with his body, senses the defender, takes a good first touch before turning, and makes the lay-off playable first time.', '4 (A, B, C, D)', 4, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 50),
  ('Midfield turn into 2v2 to goal', 'one_v_one', 'opposed', 'in_possession', 48, 48, 'Step 3: Practice 1 - Receive in Midfield, Turn and 2 v 2 Duel', NULL, 'Turning in midfield and attacking in a 2v2 duel.', 'Pitch with two big goals on the end line and two wide attacking zones in front of them; two mini goals across the middle for the defenders. Centre backs 4 and 5 at the back with balls, centre midfielders 6 and 8 at cones, wingers 7 and 11 in the zones with blue defenders.', 'Centre back 4 passes into midfielder 8, who moves off his cone to receive; the blue defender on that side goes live as soon as the ball is played. 8 turns quickly and passes to the winger in the zone, and a 2v2 is played to the big goal. Once it ends, 5 starts the same thing on the other side.', 'Attackers score in the big goal; if the defenders intercept they counter into a mini goal.', NULL, 'A firm pass along the ground lets the midfielder turn faster; midfielders check over the shoulder before receiving; turn quickly and accelerate away with the ball.', '2v2 per side, plus centre backs', 10, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 60),
  ('1v1 out wide, two goals to choose', 'one_v_one', 'passive', 'in_possession', 49, 49, 'Step 3: Practice 2', NULL, 'Stopping the ball, sharp turns and finishing in a 1v1 against a passive defender.', 'Square with a big goal behind a far end line and a second goal at the side (centre goal); attackers queue at a cone, defender waits near the far line.', 'Ball is played out wide to the attacker; the defender goes live on his first touch. Attacker either dribbles over the far line to score in the goal ahead, or cuts back and scores in the side goal.', 'Defender who wins it may score in the centre goal.', NULL, 'Attack the space ahead with conviction; shield and control the pace, then either go on or feint and turn back suddenly (outside of foot, step over or Cruyff turn).', '1v1 plus server', 3, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 70),
  ('Check away, receive and turn with pressure from behind', 'one_v_one', 'opposed', 'in_possession', 51, 51, 'Step 4: Practice 1', NULL, 'Checking away from a marker, receiving with an open body shape, turning and finishing with a defender behind.', 'Two full backs wide and two centre backs centrally on a half line; midfielder/attacker with a defender on his back; two mini goals at the far end, one at the near end.', 'A full back passes back to a centre back; the midfielder checks away from his marker then receives the next pass and plays a live 1v1, turning to score in either far mini goal.', 'Defender who wins it scores in the mini goal at the other end.', 'Grow it into a 2v1 or 2v2 duel.', 'Low start with bent knees then a diagonal or curved run to the ball; feel the defender and use the body to protect; turn away quickly (inside/outside, step over, Cruyff) then change rhythm.', '1v1 + 4 servers', 6, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 80),
  ('Create space and turn in one movement', 'one_v_one', 'opposed', 'in_possession', 52, 52, 'Step 4: Practice 2', NULL, 'Creating space, receiving and turning in one movement, then dribbling past a defender.', 'Square with two outside players on opposite sides, two inside players and two defenders (one waiting outside).', 'An outside player passes to an inside player, who must find space, turn and dribble the ball over the line on the opposite side; the defender tries to stop him. Whoever loses the ball becomes the defender.', 'Inside players may not pass to each other; outside players may not pass to each other. After 4 successful dribbles out a new defender comes in.', 'Change the size of the square to make it harder or easier; practise turns such as the V-drag, step over, letting the ball run, inside/outside hook.', 'Feint a pass back before turning sharply; know where the defender is so the turn happens before he arrives.', '2 outside + 2 inside + 2 defenders', 6, 6, NULL, NULL, NULL, NULL, false, false, true, 'U12-U13', 90),
  ('Attack the space with side and frontal pressure', 'one_v_one', 'opposed', 'in_possession', 53, 53, 'Step 4: Practice 3', NULL, 'Dribbling and finishing under pressure from a defender alongside and then in front.', 'Area with two mini goals at the far end each behind a dashed line, a goal at the near end; player A and player B start on opposite sides with one defender.', 'A dribbles at speed for the line with the defender tracking from the side; past the line he scores in the mini goal, or turns back and passes to B. B then dribbles forward with the defender now facing him, trying to cross the other line and score.', 'Defender who wins it scores in the goal at the opposite end.', NULL, 'Attack the space with confidence; hold the defender off with strength or hold and turn back; a feint before turning helps.', '2v1 (alternating 1v1s)', 3, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 100),
  ('Build-up from goalkeeper through the centre back', 'combination', 'unopposed', 'in_possession', 58, 59, NULL, NULL, 'Building up from the goalkeeper to the centre back and on to the full backs, finishing with a shot.', 'Half pitch plus; goalkeeper in goal, a crosser out wide, centre back (5), full backs (2 and 3) by cones, a No.10 by a cone at halfway, a second goal with keeper at the far end.', 'A cross is delivered to the keeper, who rolls it out and passes to the centre back; 5 turns in one movement and finds a full back, who plays into the No.10. The No.10 lays off for the full back to shoot or turns and shoots himself. Run it on both sides.', 'How to win: 10 repetitions, count the goals.', NULL, 'Accurate cross the keeper can catch; keeper passes when the centre back is ready; centre back moves diagonally as if leaving a marker, receives on the half turn with the outside of the foot; full backs start wide and push high; No.10 protects the ball with a good first touch.', '2 GK + 5-6 players', 7, 8, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 110),
  ('Build-up through the full backs: combinations', 'combination', 'unopposed', 'in_possession', 60, 61, NULL, NULL, 'Building up from the back down the flank through the full backs with set combinations ending in a shot.', 'Two centre backs with balls on the edge of the box, full backs and centre midfielders by cones, a striker on halfway, goal with keeper at the far end.', 'A: CB to right back, one-two with the centre midfielder, pass into the striker who turns and shoots. B: CB to left back, straight into the striker who lays off to the midfielder making a third-man run to shoot. C: as A but the striker sets the midfielder to shoot.', NULL, 'Players invent their own Combination D to build creativity.', 'CB plays into space in front of the full back with good weight and coaches those ahead; midfielder checks off the cone then runs diagonally and receives on the half turn; striker does not come to the ball too early and weights the set-back well.', '7 + GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 120),
  ('CB receives from keeper, build-up through centre', 'combination', 'unopposed', 'in_possession', 62, 63, NULL, NULL, 'The keeper passing to a centre back and building up through the middle to a first-time finish.', 'Keeper in goal, centre back (5) and defensive midfielder (6) by cones, No.10 by a cone near the centre circle, two mini goals wide on halfway.', 'The centre back makes a curved run off his cone and the 6 also moves to offer; keeper passes to 5, who opens up and plays into the No.10. The 10 sets the ball to the 6, who shoots first time into the mini goal on that side. Alternate sides each time.', 'How to win: 20 repetitions, 15 goals needed.', NULL, 'Keeper passes on time with weight so the CB can turn in one movement, and coaches him; CB on the half turn with outside of foot and sees the space ahead; 6 first checks back into support then goes forward; 10 sets with the outside of the foot so a first-time shot is possible.', 'GK + 3 per side', 4, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 130),
  ('Build-up from the back: two keepers, combinations', 'combination', 'unopposed', 'in_possession', 64, 65, NULL, NULL, 'Building up from the back with different combinations on both sides at once.', 'Two keepers in the box with balls; centre back, defensive midfielder, full backs at cones, two No.10s; a big goal and mini goals out wide near halfway.', 'A: keeper to CB who checks off a cone, CB to right back, one-two with the dropping 10, right back chips a mini goal over the big goal. B: keeper to the 6, 6 into the 10 who sets the left back, who has checked off his cone, to run on and score.', 'How to win: 20 repetitions, 15 goals needed.', 'Players create Combination C themselves.', 'Keeper passes on time with the right weight and coaches; CB receives on the half turn with the outside of the foot and scans ahead; 6 times his move; 10 passes with the outside of the foot so the full back can finish first time.', '2 GK + 6', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 140),
  ('Build-up through centre, spread to the flank', 'combination', 'unopposed', 'in_possession', 66, 67, NULL, NULL, 'Building up through a centre back pair and the midfield, then spreading the ball wide and finishing with a diagonal shot.', 'Keeper in goal, two centre backs (4, 5), wide centre midfielders 6 and 8 at cones, two mini goals near halfway on each side.', 'Keeper passes to 4, who drops and sets for 5 who has stepped up; 5 plays wide to the 8, who receives and turns in one movement and shoots diagonally into the far-side mini goal. 4 alternates sides; on the left the 6 receives and shoots at the right-hand goal.', 'Max 2 touches for the midfielders to receive and shoot.', NULL, 'Keeper rolls or throws to the right speed; first CB sets with the outside of the foot; second CB is patient, scans and plays hard and accurate; midfielders look over the shoulder and receive on the half turn; controlled instep shot.', 'GK + 4', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 150),
  ('Switch across the back line, long ball, 2v1', 'combination', 'opposed', 'in_possession', 68, 69, NULL, NULL, 'Switching play across the back four, an aerial pass to the striker, then a 2v1.', 'Back line of right back, centre back and left back by cones with balls; No.10 near the centre circle; two big goals at halfway; end zone with striker, a defender and two mini goals.', 'Right back passes to the centre back who switches to the left back; the left back checks off his cone and plays a long aerial ball to the striker. Then the defender goes live and the 10 joins for a 2v1 to score in a mini goal. Alternate sides.', 'Defender who wins it scores by dribbling between the two big goals. How to win: 12 long balls, count the goals.', NULL, 'Right back passes in front of the CB with weight; CB leaves the space then moves into it and passes ahead of the left back; left back scans and hits a long accurate ball at the striker''s chest.', '5 + 1 defender', 6, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 160),
  ('Flank combination, cross and finish', 'finishing', 'unopposed', 'in_possession', 70, 71, NULL, NULL, 'Midfield movement, passing and receiving in a positional flank combination ending in a cross and finish.', 'Players in their match positions on cones: 6, 8, 10, striker 9, wingers 7 and 11, goal with keeper.', 'The 10 passes to the 8, who plays into the striker; 9 drops and sets back for the 10, who plays wide and high for the right winger to run onto. The winger dribbles on and crosses; the 9 and the far winger attack the box to score.', 'How to win: 10 repetitions, count goals.', 'Go left through the left centre midfielder and left winger; players decide which side.', 'Midfielders scan and pass weighted balls away from the imaginary defender; striker checks off the cone and sets with the outside of the foot at an angle; 10 does not arrive too early and opens to the flank; wingers keep the space free and time their run.', '6 + GK', 6, 7, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 170),
  ('Flank combination and cross v defenders', 'finishing', 'opposed', 'in_possession', 72, 73, NULL, NULL, 'The same positional flank combination with crossing and finishing, now against defenders.', 'No.10 (A), centre midfielder (B), wingers (C, D) and a striker (E) on both sides; goal with keeper; one or two defenders in the box; two mini goals outside the box.', 'A passes back to B, who plays wide to winger C; C dribbles on and crosses. Striker E attacks the near post and the far-side winger D the far post.', 'Defenders who win it score in a mini goal outside the box. How to win: two sides compete, first to 5.', 'Start with no defender, then one, then two; work both sides alternately.', 'B opens to the flank before receiving and passes on time; scan the space ahead; striker loses his marker and attacks the space in front of the keeper; time the far-post run.', '5 v 1-2 + GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 180),
  ('Beat the full back 2v1 on the flank', 'combination', 'opposed', 'in_possession', 74, 75, NULL, NULL, 'Getting past a full back on the flank in a 2v1 with quick combinations, then crossing and finishing.', 'Cone gate with a defender on each flank; full backs with balls, centre midfielders by a cone, wingers, striker in the middle, goal with keeper.', 'The full back passes to the midfielder who has checked off his cone; the midfielder and winger then beat the defender through the gate by: one-two and give again, one-two and receive behind, winger dribbles past, or winger with a full back third-man run. The ball carrier then crosses for the striker (near post) and far winger (far post).', 'If the defender wins it, restart on the other side. How to win: 20 repetitions alternating sides; a headed goal counts double.', NULL, 'Full backs pass with weight and coach; midfielder checks off the cone, receives and dribbles forward; on options 1 and 2 draw the defender in before the final ball to open space behind.', '2v1 per flank + striker + GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 190),
  ('Switch play and timed runs into the box', 'finishing', 'opposed', 'in_possession', 76, 77, NULL, NULL, 'Switching the point of attack and varying runs into the penalty area.', 'Wingers 7 and 11 with balls at cones wide, centre back/defensive midfielder 5, centre midfielders 6 and 8, No.10, striker; two mini goals at the edge of the box; one defender and keeper in the box.', 'The 6 runs forward; 11 passes back to 5, who lifts an aerial pass over a mini goal for 7 to run onto; 7 dribbles and crosses. The 9 goes near post, 11 far post and the 10 arrives late for the cut-back, against one defender. Then restart from the right so the ball switches to the left.', NULL, 'Vary which area each runner attacks as long as all areas are covered.', 'First pass with correct weight; the 6''s run drags his marker to free the pass back; 5 strikes with the instep, lifting only slightly; winger keeps space high and times his entry.', '8 + 1 defender + GK', 9, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 200),
  ('Back-to-goal receiving, turn and finish', 'one_v_one', 'passive', 'in_possession', 78, 79, NULL, NULL, 'Movement and technique for receiving with an opponent behind, turning and finishing.', 'Two channels on the edge of the box; feeders (A) with balls, strikers (B) with a cone or defender behind; goal with keeper and two mini goals at halfway.', 'Feeders pass to the forwards alternately; each checks off his marker, receives back to goal, turns and shoots past the keeper.', 'With cones or passive defenders: strikers v keeper to a target number; with live defenders, attackers v defenders for most goals (defenders score in mini goals).', 'Cones, then passive defenders, then fully active defenders.', 'Feel the defender with the arms to decide which way to turn; check away first and push off him; body between defender and ball; feeder makes eye contact and plays away from the defender with pace.', '2 feeders + 2 strikers (+2 defenders) + GK', 5, 7, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 210),
  ('Target man play and finishing', 'combination', 'passive', 'in_possession', 80, 81, NULL, NULL, 'Deep striker skills: turning away and setting the ball.', 'Two sides at once with players A, B, C and a passive defender per side; a goal with keeper at each end and a mini goal in the centre.', 'Combinations: A to B to C who checks off, turns and shoots; A to B, one-two with C, B shoots; A to B to C, A runs to the by-line, C slips him in, A crosses for C; or free play. After each attack players move to the other side.', 'Defender who wins it (progression) scores in the central mini goal. How to win: two teams, first to 5.', 'Make the defender fully active; add players for intensity; move cones to change angles.', 'A passes with the outside of the foot and leaves the by-line space; B does not rush forward, receives with the outside and takes it in one movement; C checks away, receives with the inside of the left foot and shoots with the right.', '3 + 1 defender per side + 2 GK', 8, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 220),
  ('No.10 and striker combination play', 'combination', 'unopposed', 'in_possession', 82, 82, NULL, NULL, 'Attacking combination play between the No.10 and the striker.', 'Area in front of the box marked with cones; a No.10, a striker and 3 feeders with balls in the centre circle; goal with keeper.', 'Players check away and create space; options: 10 receives, turns and one-twos with the 9 to shoot; same but 9 turns and shoots; feeder plays straight into 9 who turns and shoots; or 9 sets for the 10 to shoot. Work left and right; rotate feeder to 10, 10 to striker, striker to feeder.', NULL, 'Add a defender who scores in a mini goal at the other end if he wins it.', NULL, '5 + GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 230),
  ('1v1 beat the defender and score', 'one_v_one', 'opposed', 'in_possession', 86, 86, '1 v 1 Duels: Practice 1', NULL, 'Attacking 1v1s with dribbling and moves to beat.', 'Area with two mini goals at each end; servers A and C wide with balls, attackers B1 and B2 waiting, defenders by the far goals.', 'A passes to B1 who steps forward and tries to beat the defender to score in a far mini goal. Then C serves B2 on the other side as the next defender moves across.', 'Defender who wins it scores at the opposite end; A and B1 swap. How to win: attackers v defenders, first to 5.', NULL, 'Good first touch and positive attitude; draw the defender into position then accelerate into space with a turn or move.', '1v1 + servers', 6, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 240),
  ('1v1 with frontal pressure', 'one_v_one', 'opposed', NULL, 87, 87, '1 v 1 Duels: Practice 2', NULL, 'Attacking and defending in 1v1s with the defender coming from in front.', 'Penalty-box-sized area with cones narrowing toward the attackers'' end; attackers start between two mini goals, defenders at the opposite line.', 'The attacker dribbles to score by crossing the far line; the defender closes him down and tries to win it and score in one of the two mini goals.', 'Roles swap when the defender scores.', NULL, 'Defender closes down as fast as possible and pushes the attacker back, forcing his weaker foot; the further the attacker gets, the more space he has.', '1v1', 2, NULL, 'Penalty box size', 40.3, 16.5, NULL, true, false, true, 'U12-U13', 250),
  ('Receive out wide, 1v1 then v keeper', 'one_v_one', 'opposed', 'in_possession', 88, 88, '1 v 1 Duels: Practice 3', NULL, 'Attacking 1v1s with moves to beat and finishing past a keeper.', 'Two big goals with keepers on the edge of the box; wingers (B) and defenders on each flank; servers (A) at mini goals by halfway.', 'A passes to the winger B, who duels the defender and tries to score past the keeper. Alternate left and right.', 'Defender who wins it scores in the mini goal at the other end. How to win: first to 5; if defenders win they choose the next defenders.', NULL, 'Check away and receive on the half turn; keep the first touch close; feint inside/outside and change direction; lure the defender before attacking the space behind.', '1v1 + GK per side', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 260),
  ('1v1 receiving with back to goal', 'one_v_one', 'opposed', 'in_possession', 89, 89, '1 v 1 Duels: Practice 4', NULL, 'Attacking 1v1s while receiving with the defender behind.', 'Area from halfway to the edge of the box; two servers with balls wide, attacker and defender in the middle, goal with keeper ahead and a goal with keeper behind.', 'Either server passes in; the attacker checks off, receives and either plays back or turns to beat the defender and score past the keeper. He gets 3 balls in total to score.', 'Defender who wins it scores in the goal at the other end. How to win: attackers race to be quickest to score.', NULL, 'Feel where the defender is; after checking away make a diagonal run to receive.', '1v1 + 2 servers + 2 GK', 6, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 270),
  ('1v1 duel then 1v1 with goalkeeper', 'one_v_one', 'opposed', NULL, 90, 90, '1 v 1 Duels: Practice 5', NULL, 'Attacking and defending in a 1v1 with the defender in front, plus the keeper.', 'Penalty-box-sized area, goal with keeper and defenders at one end, a mini goal in the middle of the other end with attackers either side.', 'The first attacker dribbles in; the defender steps out from beside the goal for a 1v1 and the attacker tries to beat him and the keeper. Then the second attacker goes from the other side. Run 2 or more groups.', 'Defender who wins it scores in the central mini goal. How to win: attackers v defenders, first to 5.', NULL, 'Defender and keeper work together; keeper low, one foot ahead, shows the attacker wide and stays upright until the last moment.', '1v1 + GK', 4, NULL, 'Penalty box size', 40.3, 16.5, NULL, true, true, true, 'U12-U13', 280),
  ('1v1 queue race in the penalty area', 'one_v_one', 'opposed', NULL, 91, 91, '1 v 1 Duels: Practice 6', NULL, 'Attacking and defending in 1v1s and finishing in the box.', 'Penalty-box-sized area; 3 cones (A, B, C) with attacker queues along one line; 3 defenders beside the goal with a keeper.', 'A dribbles toward goal and a defender steps out for a 1v1; score and you move to the next cone''s queue, fail and you rejoin your own. The next player from B goes against a new defender.', 'How to win: first player to work round all cones back to his own (A to B to C to A).', NULL, NULL, '3 attackers + 3 defenders + GK', 7, NULL, 'Penalty box size', 40.3, 16.5, NULL, true, true, true, 'U12-U13', 290),
  ('Continuous 1v1s with back to goal', 'one_v_one', 'opposed', 'in_possession', 92, 92, '1 v 1 Duels: Practice 7', NULL, 'Creating space, receiving with the back to goal and turning in a 1v1.', 'Penalty-box-sized area, goal with keeper at one end, mini goal in the middle of the other end; servers A and B with balls either side of it.', 'A passes to the attacker who has a defender behind; he must turn, beat him and score. Then A becomes attacker, attacker becomes defender and defender becomes server; B then serves on the other side.', 'Defender who wins it scores in the mini goal. Run 2 or more groups.', NULL, 'Check away with a diagonal run and feel the opponent; defender tries to get in front without fouling.', '1v1 + 2 servers + GK', 5, NULL, 'Penalty box size', 40.3, 16.5, NULL, true, true, true, 'U12-U13', 300),
  ('Four-channel 1v1 gauntlet', 'one_v_one', 'opposed', NULL, 93, 93, '1 v 1 Duels: Practice 8', NULL, 'Receiving, attacking and defending in fully competitive 1v1s.', 'Four channels side by side, each with a mini goal at the far end and a defender; passers on the start line.', 'In each channel a pass is played to the attacker who duels the defender to score in the mini goal; the defender scores by dribbling over the start line. The winner moves on to the next channel as passer; if the attacker wins the defender stays, if the defender wins the attacker takes his place; the passer becomes the attacker.', 'How to win: first to score in all 4 channels.', NULL, NULL, '4 groups of 1v1 + passers', 12, NULL, NULL, NULL, NULL, NULL, true, false, true, 'U12-U13', 310),
  ('Sprint, shield the ball and finish', 'one_v_one', 'opposed', 'in_possession', 94, 94, '1 v 1 Duels: Practice 9', NULL, 'Acceleration, strength, shielding and finishing.', 'Penalty-box-sized area, goal with keeper at one end, mini goal in the middle of the other with servers A and B either side; attacker and defender start together; 2 players resting outside.', 'A plays the ball ahead; the attacker sprints onto it with the defender tracking, shields it and shoots past the keeper. Then A becomes defender, defender attacker and attacker moves to A; B starts the next one from the other side.', 'Defender who wins it scores in the mini goal. How to win: defenders start 2-0 up and must hold it for 8 minutes.', NULL, 'Defender does not dive in (tackle is the last resort); attacker dribbles at speed and uses his body to shield.', '1v1 + servers + GK', 6, NULL, 'Penalty box size', 40.3, 16.5, NULL, true, true, true, 'U12-U13', 320),
  ('Two-phase 1v1 on the flank with transition', 'transition', 'opposed', 'to_attack', 95, 95, '1 v 1 Duels: Practice 10', NULL, 'Attacking and defending 1v1 on the flank and an introduction to transition.', 'Wide area near the box; one attacker plays the ball ahead of a second attacker; a defender by a cone; goal with keeper and a mini goal further out with a third attacker next to it.', 'The first attacker plays it into space for the second who tries to score; the defender cuts him off. If the defender wins it he turns back (or uses the keeper) to score in the mini goal, while the attacker by the mini goal steps up to win it back and score past the keeper.', 'Rotate: first attacker becomes second, second goes to the cone.', 'After 1v1s expand to 2v2, 3v3 and 4v4.', NULL, '3 attackers + defender + GK', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-U13', 330),
  ('1v1 circuit: front, side and behind', 'one_v_one', 'opposed', NULL, 96, 96, '1 v 1 Duels: Practice 11', NULL, 'Different 1v1 types in a circuit: frontal pressure, side pressure and pressure from behind.', 'Three zones within half a full pitch, each with a big goal at the far end.', 'A) Frontal: attacker gets the ball wide and duels, scoring in the big goal; defender scores by passing back to the server. B) Side: two keepers play the ball forward and two players race for it; attacker scores in the big goal, defender by passing to the keeper. C) Behind: two players pass, one feeds the attacker for a 1v1; attacker scores in the goal, defender by dribbling over the line.', NULL, NULL, 'A) defender stays low with bent knees and does not step in; B) attacker puts his body between defender and ball; C) defender times getting in front to win it.', '3 zones of 1v1', NULL, NULL, 'Half a full pitch', NULL, NULL, NULL, true, true, true, 'U12-U13', 340),
  ('2v1 defending dribble-over-line duel', 'one_v_one', 'opposed', 'out_of_possession', 98, 98, '2 v 1 Positional Play: Defending in a 2 v 1 Situation', NULL, 'Builds a lone defender''s defending and decision making when outnumbered two against one.', 'Rectangle with an end line marked by cones; three groups queue at three spots - two attacking groups on the start line (A with balls, B) and the defender group (C) at the far end line.', 'A passes to B and both attack the defender C, who steps up to meet them; attackers score by dribbling over C''s line. If C wins it he counters by dribbling over the opposite line. After each go players rotate groups A to B, B to C, C to A.', 'Out of play: the team that did not kick it out dribbles back in. If the defender scores, the two attackers do 10 push-ups.', NULL, 'Mental side matters - isolate the ball carrier; do not dive in or overcommit, avoid being beaten too easily.', '2v1, 3 groups', 6, 12, NULL, NULL, NULL, NULL, false, false, true, 'U12-13', 350),
  ('2v1 plus keeper defending to goal', 'one_v_one', 'opposed', 'out_of_possession', 99, 99, '2 v 1 Positional Play: Defending in a 2 v 1 (+GK) Situation', NULL, 'Teaches the defender and goalkeeper to work together against two attackers.', 'Penalty-box-sized area with a full goal and keeper at one end and a mini goal in the centre of the far line; attackers A (with balls) and B start near the goal line, defender C in the middle; several groups can run at once.', 'A passes back to B, B passes on to C (attacker) and it becomes 2 attackers against defender plus GK. If the defender wins it he tries to score in the central mini goal; if the keeper gathers it he rolls it out for the defender to score.', 'Rotate A to B to C to A after each attack; switch roles when the defenders have scored 3 times.', 'Can also be played 2v2, 2v3 and 3v3.', 'Defender and keeper must collaborate - each takes or covers one attacker so the attackers have to make a decision.', '2v1+GK', 4, NULL, 'Penalty box size', NULL, NULL, NULL, true, true, true, 'U12-13', 360),
  ('Keeper to centre backs build-up 2v1', 'one_v_one', 'opposed', 'in_possession', 100, 100, '2 v 1 Positional Play: Building Up Play from the Goalkeeper Through the Centre Backs in a 2 v 1 Situation', NULL, 'Practises building out from the goalkeeper through two centre backs.', 'Penalty area and its width out to a line about 25-30 m from goal, with two mini goals beyond the line; GK in goal, two centre backs and one blue forward marking them; balls with a server by the post.', 'Server plays the ball into the GK who controls it with his feet; the two centre backs shake off the forward to receive, creating a 2v1. CBs score by dribbling over the line and into either mini goal; the forward tries to win it and score past the GK.', 'Forward''s goals count double. Roles change after a goal.', NULL, 'CBs spread wide to receive and control with the outside of the foot; GK only passes when a CB is free and aims as far up the pitch as possible.', '2v1+GK', 4, 6, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 370),
  ('2v1 crossing and finishing from both flanks', 'finishing', 'opposed', 'in_possession', 101, 101, '2 v 1 Positional Play: Exploiting a 2 v 1 Situation in Front of Goal to Score', NULL, 'Use a 2v1 in front of goal well - crossing and finishing with good decisions.', 'Half pitch with a goal at each end (main goal with GK at the top, a full goal with GK at halfway), plus a mini goal in the centre; on each side a passer A deep and a wide player B; an attacker C and a defender in front of each goal.', 'Both sides start at the same time: A passes out wide to B, who dribbles and crosses; B and central attacker C play 2v1 against the defender to score (near/far post, cut-back etc.). If the defender wins it he scores in the central mini goal.', 'Race to see which side scores 4 first.', NULL, 'A''s pass must be accurate and he then coaches B; B stays wide and reads the attacker''s and defender''s positions; C makes himself available near post, far post, in front of GK or for the pull-back.', '2v1+GK at each end', 10, 16, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 380),
  ('No.10 and striker 3-zone duel game', 'one_v_one', 'opposed', 'in_possession', 102, 102, '2 v 1 Positional Play: Attacking Combination Between the No.10 and the Striker in a Dynamic 3 Zone Duel Game', NULL, 'Combination play between the No.10 and the striker in a fast duel game.', '30 x 45 yard area split into three 30 x 15 zones with a goal and GK at each end; a defender in the middle zone and one in each end zone with a striker.', 'The No.10 starts 1v1 in the middle zone and tries to dribble past the defender into the next zone, where he joins the striker for a 2v1 (+GK) to score. Defender and GK try to stop them.', 'If the attack stalls the No.10 may turn once and attack the other end. 1 point per goal, 2 points if the defender wins the ball in the end zone; first to 6 wins.', NULL, 'No.10 chooses between beating his man, passing to the striker in space or a one-two; striker checks away then moves diagonally to receive so the defender must decide quickly.', '1v1 then 2v1+GK', 6, 8, '30 x 45 yards (3 zones of 30 x 15)', 41.1, 27.4, NULL, true, true, true, 'U12-13', 390),
  ('2v2 flank attack crossing to goal', 'finishing', 'opposed', 'in_possession', 104, 104, '2 v 2 Positional Play: Attacking on the Flank in a 2 v 2 Crossing and Finishing Practice', NULL, 'Attacking a 2v2 out wide and in front of goal.', 'Half pitch, goal and GK at one end and a mini goal on halfway; queues of attackers and defenders on both sides at halfway with balls; a central attacker and defender in the box.', 'A player passes forward up the flank; the winger goes first and his defender follows after a short delay, giving 2v2 with the central pair. Attackers try to score past the GK; if defenders win it they score in the mini goal. Then repeat from the left.', 'Two teams race to 5 goals; goals conceded are subtracted.', NULL, 'Central attacker checks away before timing his run into the box; wide defender keeps the attacker to jogging pace and blocks the cross; central defender stays touch-tight.', '2v2+GK', 10, 16, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 400),
  ('No.10 and striker 2v2 combination', 'one_v_one', 'opposed', 'in_possession', 105, 105, '2 v 2 Positional Play: Attacking Combination Play Between the No.10 and the Striker in a 2 v 2 Situation', NULL, 'Combination play between the striker and the No.10 against two defenders.', 'Area from the edge of the penalty box back toward halfway with a goal and GK, plus two mini goals on the back line; a wide feeder, a central midfielder feeder, two forwards and two defenders.', 'The wide player passes back to the central midfielder, who steps in and passes to one of the forwards; the forwards make space, receive and play 2v2 to score past the GK. Defenders who win the ball score by passing back to the central midfielder.', 'When the defenders score twice: defenders become attackers, attackers become feeders, feeders become defenders.', NULL, 'Create space for your partner; make diagonal, not straight, runs; never both in the same area; make full use of the teammate''s run.', '2v2+GK+2 feeders', 7, 7, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 410),
  ('Build-up from keeper 2v2 to line', 'one_v_one', 'opposed', 'in_possession', 106, 106, '2 v 2 Positional Play: Building Up Play from the Goalkeeper by Moving Back to Receive in a 2 v 2 Situation', NULL, 'Building up from the back in a 2v2.', 'Penalty-box width area from goal out to a red end line; GK in goal, two orange players start on the end line marked by two blue players.', 'A pass goes to the GK who must control with his feet; the two orange players drop off to find space, receive and combine to dribble over the red line. Blues try to win it and score past the GK.', 'If blue score, the pairs swap roles.', NULL, 'GK takes a good first touch and passes only to a free player; if nobody is free he dribbles out to draw a defender and make it 3v2.', '2v2+GK', 5, 5, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 420),
  ('2v2 transition defending game', 'one_v_one', 'opposed', 'out_of_possession', 107, 107, '2 v 2 Positional Play: Defensive Collaboration in a 2 v 2 Transition Game', NULL, 'Defending ability and teamwork as a pair in a 2v2.', 'Area twice the size of the penalty box; red line at the top where orange attackers queue (A with balls, B), white line near the bottom with two mini goals behind it where blue defenders start.', 'Orange A passes to B and the pair dribble over the white line then score in a mini goal. If the blues win the ball they try to dribble over the red line at the other end.', 'If defenders score they swap with the attackers; if attackers score they stay on. A pair reaching 5 mini-goal goals sends everyone else for a jog round the pitch.', NULL, 'Defenders support and cover each other - one presses, the other blocks the pass; talk constantly; do not run backwards, close at diagonal angles to cut passes behind.', '2v2 with queues', 8, 12, 'Double the penalty box', NULL, NULL, NULL, true, false, true, 'U12-13', 430),
  ('Continuous pairs game, winners stay on', 'small_sided_game', 'opposed', NULL, 108, 108, '2 v 2 Positional Play: Continuous 3 v 3 Small Sided Games - First Goal Wins', NULL, 'Attacking and defending teamwork in a 2v2 (title says 3v3).', 'Area twice the size of the penalty box with a goal and GK at each end; 6-8 pairs waiting beside the goals; plenty of balls around the pitch.', 'Two pairs play, starting from a GK; the pair that scores stays on and has the ball next, the losing pair goes off and a new pair comes on. Ball out of play is dribbled back in by the other pair.', 'First team to 5 goals wins.', 'Can be played as 4v4 or 5v5.', 'Mark the ball carrier tightly; second defender covers the one pressing; the deepest player coaches the other.', '6-8 pairs, 2v2+2 GKs', 14, 18, 'Double the penalty box', NULL, NULL, NULL, true, true, true, 'U12-13', 440),
  ('Defending a 3v2 plus keeper', 'defending', 'overload', 'out_of_possession', 110, 110, '3 v 2 Positional Play: Defending a 3 v 2 (+GK) Attack', NULL, 'Builds understanding between the goalkeeper and two defenders; attackers practise using the 3v2 overload to score.', 'Penalty-box-sized area, full goal with GK at one end and a mini goal at the other; two blue defender pairs wait by the goal posts, orange attackers start from the far corners.', 'An attacker dribbles in from a corner and the three attackers try to score past the GK. The two defenders and GK defend and, on winning it, try to score in the mini goal opposite.', 'The defender pairs race to 3, 4 or 5 goals; goals the attackers score are deducted from the defending pair''s total.', NULL, 'When one defender steps to press the other covers; the deeper defender coaches the other; isolate the ball carrier.', '3v2+GK', 6, 10, 'Penalty box size', NULL, NULL, NULL, true, true, true, 'U12-13', 450),
  ('3v1 plus keeper attacking combination', 'combination', 'overload', 'in_possession', 111, 111, '3 v 2 Positional Play: Attacking Combination Play in a 3 v 1 (+ GK) Situation', NULL, 'Combination play between the striker, the No.10 and a supporting player.', 'Area from the edge of the penalty box back toward halfway, goal with GK at one end and two mini goals on the back line; two forwards and one defender, a supporting orange player starts deep with the ball.', 'The supporting player passes into one of the forwards and joins in for a 3v1 (+GK); the attackers use the overload, create space and score past the GK. If the defender wins it he aims at one of the two mini goals.', 'Offside applies. If the defender scores, the three attackers do 10 press-ups.', NULL, 'Commit the defender so he must choose; make diagonal runs away from him to receive in space; the defender should confront the ball carrier.', '3v1+GK', 5, NULL, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 460),
  ('Back pass to keeper, build-up 3v2', 'phase_of_play', 'overload', 'in_possession', 112, 112, '3 v 2 Positional Play: Back Pass to the Goalkeeper + Building Up Play from the Back in a 3 v 2 Situation', NULL, 'Basic principles of passing back to the keeper and building from the back with a 3v2.', 'Penalty-box-width area out from goal to a line near halfway, with cone gates in the two corners of that line; GK, three orange defenders, two blue forwards; coach with balls at the side.', 'The coach plays the ball between two players at the side; the orange player gets a 2 yard start and passes back to the GK. The three orange players then build up 3v2 (+GK) and score by dribbling through a corner cone gate; if the blues win it they shoot at the main goal.', 'Attackers and defenders race to 5 goals.', NULL, 'After the back pass the two outside players spread wide and take it on the outside of the foot; the centre back calls for it and receives on the half turn; the GK is always available for a return pass.', '3v2+GK', 6, 6, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 470),
  ('Wing play 3v2 to goal, both ends', 'finishing', 'overload', 'in_possession', 113, 113, '3 v 2 Positional Play: Wing Play: Attacking Combinations and Finishing in a 3 v 2 (+GK) Practice', NULL, 'Attacking combinations with the wingers in a 3v2.', 'Half pitch with a goal and GK at each end; wingers wait at both touchlines, central players A and B start by each goal.', 'A passes out wide to a winger and the three attackers try to score past the GK against two defenders; if the defenders win it they attack the opposite goal. After a goal B restarts and the other team has the 3v2 the other way.', 'Two teams race to 5 goals.', 'Winger beats his man and crosses; winger plays a one-two with the supporting player and gets in behind; the supporting player overlaps from behind to receive in behind and score.', NULL, '3v2+GK each way', 10, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 480),
  ('Two-zone 3v2 transition finishing game', 'transition', 'overload', 'to_attack', 114, 114, '3 v 2 Positional Play: Forward Play: Attacking Combinations and Finishing in a 2 Zone Dynamic Transition Game', NULL, 'Attacking combinations and quick transition play.', 'Half pitch split into two zones by a halfway line, a goal and GK at each end; three orange attackers v two blue defenders in one zone, and the reverse in the other, plus a teammate on the halfway line.', 'The orange midfielder dribbles inside and passes to one of two forwards, and the three try to score past the GK. When the defenders win it they pass it fast to a teammate on the halfway line, and the three blue attackers then play 3v2 the other way.', 'Two teams race to 5 goals.', NULL, 'Attackers check away before moving to receive, not always toward the ball; coach shouts ''free'' when a defender lets an attacker slip away; defenders learn to release the ball quickly after winning it.', '3v2+GK each zone', 12, 14, 'Half pitch, 2 zones', NULL, NULL, NULL, true, true, true, 'U12-13', 490),
  ('Keeper build-up 3v3 transition game', 'phase_of_play', 'opposed', 'in_possession', 116, 116, '3 v 3 Positional Play: Building Up Play from the Goalkeeper in a 3 (+GK) v 3 Dynamic Transition Game', NULL, 'Basic principles of building up from the goalkeeper in a 3v3.', 'Penalty-box-width area from goal to a white dashed line, with two mini goals just beyond the line; GK, three orange players and three blue players.', 'An orange player in the middle passes to the GK, who plays to one of the three orange players; orange score by dribbling over the dashed line and into either mini goal. If blue win it they counter to score past the GK.', 'The GK may also score in a mini goal with a long ball, counting double, so the blues cannot all push up.', NULL, 'If nobody is free the GK dribbles forward to draw a blue player; more options are better, but he should pick the one furthest up the pitch.', '3+GK v 3', 7, 7, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 500),
  ('Wing play 3v3 plus keeper to goal', 'finishing', 'opposed', 'in_possession', 117, 117, '3 v 3 Positional Play: Wing Play: Attacking Combinations and Finishing in a 3 v 3 Practice', NULL, 'Wing play - attacking down the flank and in front of goal in a 3v3.', 'Half pitch with a goal and GK at one end and a mini goal on halfway; player A central near halfway, wingers B and C on the flanks, three defenders (one starts deep by the mini goal).', 'A dribbles forward and passes to a winger; the third defender may join only once the ball has gone past him, then it is 3v3 (+GK). Defender 1 engages the winger, defender 2 covers, defender 3 recovers.', 'Goals scored after dribbling past an opponent count double.', 'Winger goes 1v1, plays a one-two with the supporting player, or the supporter runs in behind.', 'Third defender sprints back to even the numbers; A passes firmly along the ground once B is ready; the winger checks away from his marker and acts quickly.', '3v3+GK', 7, 7, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 510),
  ('Two-zone 3v3 long-range shooting game', 'finishing', 'opposed', 'in_possession', 118, 118, '3 v 3 Positional Play: Shooting from Distance in a Dynamic 2 Zone Small Sided Game', NULL, 'Shooting from distance inside a small-sided game.', 'Half pitch split into two zones at a halfway line, goal and GK at each end; 3v3 in each zone.', 'Play starts from a GK. Players cannot cross the halfway line; they either shoot from long range or pass to a teammate in the other zone.', 'First of two teams to 4 goals; a long-range goal struck from the other zone counts double.', NULL, 'Everyone works to free one player to shoot; check away from markers to create space and set a teammate up.', '6v6+2 GKs (3v3 per zone)', 14, 14, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 520),
  ('3v3 pressing gauntlet, two zones', 'defending', 'opposed', 'out_of_possession', 119, 119, '3 v 3 Positional Play: Pressing the Ball in a 3 v 3 Duel Gauntlet Competition', NULL, 'Defending by stepping forward to press and win the ball.', 'Rectangle split into two zones; one team of three blue defenders on each zone''s back line, three orange attackers at the start line with balls; two teams of each colour.', 'Orange teams get 6 attempts (3 each) to dribble across both zones; then roles swap. Defenders may only step forward once the ball enters their zone, then all press and close down the carrier.', '1 point for dribbling across the first zone, 2 points for crossing both.', 'Coach passes the ball into an attacker instead of a dribble start, making the pressing trigger more like a match.', 'Defenders keep pressure on the ball and do not back off.', '4 teams of 3', 12, 12, NULL, NULL, NULL, NULL, false, false, true, 'U12-13', 530),
  ('3v3 three-zone transition duels', 'transition', 'opposed', 'out_of_possession', 120, 120, '3 v 3 Positional Play: 3 v 3 Duels in a Dynamic 3 Zone Transition Game', NULL, 'Defending in a 3v3 with quick transitions.', 'Area split into three zones with a mini goal at each end; 3v3 in the central zone, three defenders waiting in each end zone.', 'Play 3v3 in the middle; a team that gets over a line plays 3v3 in that end zone against the next three defenders to score. End-zone defenders who win the ball pass to teammates in the central zone, who turn and attack the opposite goal. Restart after a goal or ball out.', '3 x 10 minute games, 1 point per game won, best of 3.', 'Can be played 2v2 or 4v4.', 'Defenders force attackers away from goal and shift toward the ball side.', '9-12 players (3v3 per zone)', 9, 12, NULL, NULL, NULL, 30.0, true, false, true, 'U12-13', 540),
  ('Two-zone 4v3 defend and counter', 'transition', 'overload', 'out_of_possession', 122, 122, '4 v 2 / 4 v 3 Positional Play: Defensive Positional Play + Counter Attack in a Dynamic 2 Zone Transition Game', NULL, 'Defensive positioning of a back three and their link with the goalkeeper, plus a quick counter.', 'Half pitch split into two zones by a line, a goal and GK at each end; in each zone four attackers of one team against three defenders of the other.', 'Four attackers try to score past the GK while the three defenders defend collectively. If the defenders win it they pass at once to a teammate in the other zone, where the blues now attack 4v3.', 'First to 5 goals; after a goal the other team attacks the opposite way.', 'Time limit: attackers must score inside 8-10 seconds.', 'Defenders leave the widest attacker free and keep all three central; GK and defenders communicate well.', '7v7+2 GKs (4v3 per zone)', 16, 16, 'Half pitch, 2 zones', NULL, NULL, NULL, true, true, true, 'U12-13', 550),
  ('Back three compact line-defending 3v4', 'defending', 'overload', 'out_of_possession', 123, 123, '4 v 2 / 4 v 3 Positional Play: Collective and Compact Defending (3 v 4) in a Dynamic 2 Zone Practice', NULL, 'Collaboration between three defenders.', 'Rectangle split into two zones by a central line; in zone one three defenders v four attackers, more attackers wait in zone two.', 'One attacker must dribble over the central line within a time limit (e.g. 20 seconds); defenders try to stop it. If an attacker gets through he joins three teammates in the next zone and the three defenders slide over to face a fresh 3v4 with the same aim.', 'Attacker dribbling over the line in time = 1 point; defenders preventing it = 1 point.', 'Can be played with 4 defenders.', 'Stay compact and defend the line with a side-on body shape.', '3v4 (+4 waiting)', 11, 12, NULL, NULL, NULL, NULL, false, false, true, 'U12-13', 560),
  ('4v2 keep-ball at the back', 'possession', 'overload', 'in_possession', 124, 124, '4 v 2 / 4 v 3 Positional Play: Positional Play at the Back in a 4 v 2 Dynamic Possession Exercise', NULL, 'Positional play principles for keeping the ball at the back.', 'Penalty-box-sized area (slightly narrower) in front of a goal; GK plus three orange players against two blue defenders.', 'GK and three orange keep possession inside the area; the two blues try to win it and score past the GK.', '5 passes in a row = 1 point; defenders winning it and scoring = 2 points. Player who loses it swaps with a defender; restart when the ball goes out or the GK saves.', NULL, NULL, '3+GK v 2', 6, 6, 'Penalty box size (a bit narrower)', NULL, NULL, NULL, true, true, false, 'U12-13', 570),
  ('4+GK v 2 build-up to the striker', 'phase_of_play', 'overload', 'in_possession', 125, 125, '4 v 2 / 4 v 3 Positional Play: Building Up Play and Passing to the Striker in a 4 (+GK) v 2 Dynamic Practice', NULL, 'Positional play in build-up from the back, working the ball into the striker.', 'Area from goal to a dashed line with two mini goals beyond it; GK, three orange defenders and a striker standing on the line, two blue defenders.', 'The GK starts; orange keep the ball 4v2 and look to pass into the striker on the line, who lays it back for an onrushing teammate. Orange can only score in the mini goals after the striker has had the ball. Blues who win it shoot at the main goal.', 'If the striker gets a long ball straight from the GK and sets up a scorer, the goal counts double.', NULL, NULL, '4+GK v 2', 7, 7, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 580),
  ('Numbered call build-up 4+GK v 3', 'phase_of_play', 'opposed', 'in_possession', 126, 126, '4 v 2 / 4 v 3 Positional Play: Movement to Receive, Decision Making and Building Up Play in a 4 (+GK) v 3 Practice', NULL, 'Movement to receive, quick decisions and building play out.', 'Area from goal to just past the edge of the box with two mini goals at the far end; GK with the ball, four numbered orange players, three blue defenders, coach at the side.', 'The coach calls a number and that player must move fast to get the ball from the GK; after his first touch the rest join in. If the GK cannot find him the coach calls another number. Orange aim at the mini goals; blues who win it shoot at the main goal.', 'Goal after a proper build-up from the back counts double.', NULL, 'GK can dribble out to draw a defender and free a teammate; two players spread wide and take it to feet as high as possible; defenders sit at diagonal angles behind one another.', '4+GK v 3', 8, 8, NULL, NULL, NULL, NULL, true, true, true, 'U12-13', 590),
  ('Continuous 4v3 with keepers, rotate', 'small_sided_game', 'overload', 'in_possession', 127, 127, '4 v 2 / 4 v 3 Positional Play: Continuous 4 (+GK) v 3 (+GK) Small Sided Games - First Goal Wins', NULL, 'Attacking and using a 4v3 on the flank and in front of goal.', 'Half pitch with a goal and GK at each end; four orange outfield players v three blue, the other players wait outside (two per team).', 'Orange start with the ball and four players against three. After a goal play restarts with a 4v3 in the blues'' favour. Outside players rotate in so everyone gets a rest.', 'First to 8 goals; a first-time finish from a cross counts double.', 'One attacker beats a defender 1v1 to score; one-two with the striker to get in behind; supporting player runs in behind to score.', NULL, '4v3 + 2 GKs, 4 waiting', 13, 15, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 600),
  ('Wingers, No.10 and striker attack', 'combination', 'overload', 'in_possession', 128, 128, '4 v 2 / 4 v 3 Positional Play: Position Specific Attack with Wingers, the No.10 and Striker in a Dynamic Practice', NULL, 'Attacking combinations between the two wingers (7, 11), the No.10 and the striker (9).', 'Half pitch, goal and GK at each end; two feeders by the halfway goal, the No.10 central, wingers 7 and 11 wide and striker 9 up front marked by three blue defenders.', 'The two outside players pass into the No.10; the attack goes live when the No.10 turns or a forward pass goes high up the pitch. The attackers try to score past the GK; defenders who win it attack the goal at the other end.', 'A goal straight from a through ball in behind the defence counts double.', NULL, 'Defenders cover each other''s positions; the player on the ball always looks for the pass in behind; keep movement and passing at high speed.', '4v3+GKs', 11, 11, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 610),
  ('Two-zone 4v3 attack via striker', 'small_sided_game', 'overload', 'in_possession', 129, 129, '4 v 2 / 4 v 3 Positional Play: 4 v 3 Attacks in a Dynamic 2 Zone Small Sided Game', NULL, 'Passing into the striker in behind and the third-man run to make a 4v3.', 'Half pitch split into two zones, big goal with GK at each end; zone one: GK, No.10 and two central midfielders (6, 8) v three blues; zone two: striker 9 and wingers 7, 11 v three blues.', 'From the GK, the midfield trio play past three blues into the striker in the other zone and one midfielder crosses over to make a 4v3 to score. Blues winning it in zone one shoot at that goal; blues winning it in zone two pass back to teammates in zone one to attack, while the forward-running midfielder tracks back.', 'First to 5 goals.', 'A defender may also push up into zone two, making 4v4.', 'Use the third-man run of the player crossing zones; focus is the pass to the striker in behind; use big goals with keepers.', '7v6+2 GKs', 15, 15, 'Half pitch, 2 zones', NULL, NULL, NULL, true, true, true, 'U12-13', 620),
  ('Keeper long-pass build-up, two zones', 'small_sided_game', 'opposed', 'in_possession', 131, 131, '4 v 4 Positional Play: Building Up Play from the Back with Long Passes in a Dynamic 2 Zone Practice', NULL, 'Long, accurate passing when building from the back.', 'Area twice the penalty box, split by a halfway line, goal and GK at each end; 4v4 in the far zone, the starting GK alone in his own zone.', 'The GK starts and tries to hit a long pass to a teammate in the far zone, or may shoot straight into the opposite goal (that keeper does not defend this). If no long option he may pass short in his zone, but a goal only counts once all his players are past halfway. Defenders who win it counter to score.', 'A long pass from the GK straight into the goal counts double.', NULL, 'First choice is the furthest-forward player; players move into space away from markers to be available; defenders work together to protect the goal since the GK can score.', '4v4+2 GKs', 10, 10, 'Double the penalty box', NULL, NULL, NULL, true, true, true, 'U12-13', 630),
  ('Wing play SSG with side zones', 'small_sided_game', 'opposed', 'in_possession', 132, 132, '4 v 4 Positional Play: Wing Play in a Dynamic Small Sided Game with Side Zones', NULL, 'Beating the full back and creating chances from the flank.', 'Half pitch split into two zones with side channels down both flanks, goal and GK at each end; zone one: orange defender v blue forward; zone two: orange forward v three blue defenders; two orange wingers in the side zones.', 'The orange defender passes to a winger, who tries to make a chance for the forward and the far winger running into the box. Defenders who win it counter to the goal at the other end.', 'Any goal counts, but a goal straight from a winger''s cross counts double.', NULL, 'Look to pass to the winger in space; play it fast and away from the defender; winger moves toward the ball to receive, is positive 1v1 and can use a supporting runner high up the flank.', '4v4+2 GKs', 10, 10, 'Half pitch, 2 zones + side zones', NULL, NULL, NULL, true, true, true, 'U12-13', 640),
  ('Position-specific 4v4 two-zone game', 'small_sided_game', 'opposed', 'in_possession', 133, 133, '4 v 4 Positional Play: Position Specific 4 v 4 Attacks in a Dynamic 2 Zone Small Sided Game', NULL, 'Combination play between striker 9, No.10 and wingers 7 and 11 in and around the box.', 'Half pitch split into two zones, goal and GK at each end; 4v4 in both zones - orange full backs and centre backs/midfielders in zone one, orange wingers, No.10 and striker in zone two.', 'From the GK, the back four pass into a teammate in zone two (the No.10 may drop briefly into the low zone to receive); the four attackers try to score 4v4. If blue win it they pass to teammates in zone one, who attack 4v4 the same way.', NULL, 'The passer may push forward to make 5v4 in the second zone.', 'Pass to the player furthest forward and away from his marker.', '8v8+2 GKs', 18, 18, 'Half pitch, 2 zones', NULL, NULL, NULL, true, true, true, 'U12-13', 650),
  ('4v4 man-marking to six cone goals', 'defending', 'opposed', 'out_of_possession', 134, 134, '4 v 4 Positional Play: Man to Man Marking in a 4 v 4 Small Sided Game with 6 Target Goals', NULL, 'Defending by squeezing play and pressing the ball carrier with man-to-man marking.', 'Rectangle with three small cone targets on each end line (six in all); 4v4, orange can use set roles (one centre back, two full backs, a centre midfielder).', 'Orange keep the ball, free a player and pass into any of the six cone targets to score. Each blue picks up a man to stop him receiving in space; if blue win it they pass into a cone target to score themselves.', 'Roles switch after 3 rounds; the two teams compete.', NULL, 'Never let your man get away - keep moving and anticipate; keep pressure on, especially when he tries to shoot at the cones, which spoils his accuracy.', '4v4', 8, 8, NULL, NULL, NULL, NULL, true, false, false, 'U12-13', 660),
  ('4v5 two-zone deny the through ball', 'defending', 'opposed', 'out_of_possession', 136, 136, '5 v 4 Positional Play: Defensive Shape and Preventing Through Balls in a 4 v 5 Dynamic 2 Zone Practice', NULL, 'Collective defending, shape and pressing to stop through balls.', 'Half pitch split into two zones by a line, one goal with GK; zone one: four orange v three blue; zone two: an orange striker marked by one blue defender.', 'Orange in zone one try to play a through ball into the striker in zone two; once that happens everyone may move into zone two for a 5v4 attack. Blues squeeze the space in zone one, block through balls and try to win it, then score in the goal.', 'Blues winning it in zone one and scoring = 2 goals; winning it in zone two and scoring = 1. Restart from the beginning after any goal.', NULL, 'Pressure the ball so the carrier has no time to look up and pick a pass; keep gaps between defenders small and do not get beaten easily 1v1.', '5v4', 9, 10, 'Half pitch, 2 zones', NULL, NULL, NULL, true, true, true, 'U12-13', 670),
  ('Position-specific 5v4 attack to goal', 'phase_of_play', 'overload', 'in_possession', 137, 137, '5 v 4 Positional Play: Position Specific 5 v 4 Attack in a Dynamic Practice', NULL, 'Attacking combinations between striker 9, No.10, wingers 7 and 11 and a central midfielder (6 or 8) in the opposition half.', 'Opposition half with a goal and GK, two mini goals near the halfway line; two orange centre midfielders by halfway, No.10, wingers and striker forward, four blue defenders (one starts by a mini goal).', 'One centre midfielder passes into the No.10; on that pass the other midfielder and the defender by the mini goal join in, making 5v4 (+GK). The five combine to score past the GK; if defenders win it they aim at a mini goal.', 'Game starts 1-0 to the defenders; first to 3 goals.', NULL, 'No.10 turns or plays back to the joining midfielder depending on the defender; with enough space, play into the striker high up.', '5v4+GK', 10, 10, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 680),
  ('5v5 SSG, keeper starts build-up', 'small_sided_game', 'opposed', 'in_possession', 139, 139, 'Match Specific 5 v 5 Small Sided Games: Building Up Play with the Goalkeeper in a 5 v 5 Small Sided Game', NULL, 'Gets the goalkeeper involved in the possession phase.', 'Half pitch, penalty-box width, goal and GK at each end; 5v5.', 'The GK dribbles out with the ball; players shake off markers to get a pass from him, aiming to feed the striker to score. Defenders who win it counter to score past the GK. Ball out of play restarts with the orange GK.', 'Goals that come from a build-up starting with the GK count double.', NULL, 'Check away before moving to receive; the striker especially must find space to be available.', '5v5+2 GKs', 12, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 690),
  ('5v5 SSG, beat the full back first', 'small_sided_game', 'opposed', 'in_possession', 140, 140, 'Match Specific 5 v 5 Small Sided Games: Beating the Defender on the Flank in a 5 v 5 Small Sided Game', NULL, 'Wing play - making chances from the flanks.', 'Half pitch with marked side channels, goal and GK at each end; 5v5 including wingers v full backs on the flanks.', 'Normal 5v5, but wingers must get past their direct opponent on the flank 3 times before they may cross into the box. Defenders are not told this is the focus. Track how long the wingers take; defenders who win it counter at the other goal.', 'First to 5 goals; a goal direct from a cross counts double.', NULL, NULL, '5v5+2 GKs', 12, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 700),
  ('5v5 SSG, striker hold-up and turn', 'small_sided_game', 'opposed', 'in_possession', 141, 141, 'Match Specific 5 v 5 Small Sided Games: Individual Play from the Striker in a 5 v 5 Small Sided Game', NULL, 'Individual play by the striker within a 5v5.', 'Half pitch, penalty-box width, goal and GK at each end; 5v5.', 'Normal 5v5 focusing on the striker. When an orange player makes a move (turn or beat a man), the striker''s marker must touch the ground with both hands for a second, giving the striker a head start to run into space. The marker can also be given set tasks (e.g. step in front of the striker when he is passed to) so he learns to attack in different ways.', 'A goal or assist from the striker counts double. Defenders who win it try to score in the mini goal (text says mini goal; diagram shows a full goal).', 'Vary the marker''s task to change the problem the striker faces.', 'Shield the ball with the body between defender and ball; feel where the defender is and use good body shape on receiving; keep the ball away from him and make chances.', '5v5+2 GKs', 12, 12, 'Half pitch', NULL, NULL, NULL, true, true, true, 'U12-13', 710)
) AS v(t, cat, opp, m, pf, pt, ref, coach, obj, setup, proc, rules, prog, cp, players, mn, mx, area, len, wid, dur, goals, gk, dir, age, so)
JOIN exercise_categories c ON c.code = v.cat
CROSS JOIN (SELECT id, source_id FROM coaching_books WHERE slug = 'dutch-academy-football-coaching-u12-13-technical-and-tactical-practices-from-top') b;
INSERT INTO schema_migrations (filename) VALUES ('2407-exercises-book-dutch-academy-football-coaching-u12-13-technical-and-tactica.sql') ON CONFLICT DO NOTHING;
COMMIT;
